extern "C" __global__ void predict(float4* pos,float4* old,float4* vel,int n,float dt,float r,int* error,float4* predicted

 ,const float4* plant,float4 feed_brake,float brake_rate,float4 feed_brake_b,float brake_rate_b,float4 feed_brake_c,float brake_rate_c,
 float4 feed_brake_d,float brake_rate_d,float4 feed_brake_e,float brake_rate_e,float4 feed_brake_f,float brake_rate_f










 ){
 int i=get_global_id(0);if(i>=n)return;r=grain_radius(pos[i].w,r);float3 v;float3 external=float3(0,0,-9.81f);






















 float3 air=plant_air(pos[i].xyz(),plant);float rho=plant[1].w,re=1.2f*(2*r)*length(air-vel[i].xyz())/1.81e-5f;float cdre=re<1000?24*(1+.15f*cl_pow(re,.687f)):.44f*re;float beta=3*1.81e-5f*cdre/(16*rho*r*r);v=(vel[i].xyz()+dt*(external+beta*air))/(1+dt*beta);


 const float4 brakes[6]={feed_brake,feed_brake_b,feed_brake_c,feed_brake_d,feed_brake_e,feed_brake_f};
 const float rates[6]={brake_rate,brake_rate_b,brake_rate_c,brake_rate_d,brake_rate_e,brake_rate_f};
 for(int b=0;b<6;++b){
  const float2 offset=pos[i].xy()-brakes[b].xy();
  if(rates[b]>0.f && pos[i].z>=brakes[b].z && dot(offset,offset)<=brakes[b].w*brakes[b].w){
   v=(vel[i].xyz()+dt*(external+float3(0,0,9.81f)+beta*air))/(1.f+dt*(beta+rates[b]));
   break;
  }
 }
 if(!isfinite(beta)||length(air-vel[i].xyz())>100.f||re>200000.f||beta*dt>.1f){atomic_or(error,32);return;}
 if(any(pos[i].xyz()<plant[2].xyz())||any(pos[i].xyz()>plant[3].xyz())){atomic_or(error,1);return;}











 old[i]=pos[i];
 if(!all(isfinite(v))||length(v)*dt>r*.5f){atomic_or(error,2);return;}




 pos[i].set_xyz(pos[i].xyz()+v*dt);predicted[i]=pos[i];vel[i]=float4(v,0);
}

__device__ float3 boxpush(float3 p,float3 h,float r){

 if(any(cl_fabs(p)>h+float3(r)))return float3(0);

 float3 q=clamp(p,-h,h),d=p-q;float len=length(d);
 if(len>1.e-9f)return len<r?d*((r-len)/len):float3(0);
 float3 gap=h-cl_fabs(p);int axis=gap.x<gap.y?(gap.x<gap.z?0:2):(gap.y<gap.z?1:2);float3 out=float3(0);out[axis]=(p[axis]>=0?1.f:-1.f)*(gap[axis]+r);return out;
}
__device__ float3 rotatex(float3 p,float a){float s=cl_sin(a),c=cl_cos(a);return float3(p.x,c*p.y-s*p.z,s*p.y+c*p.z);}
__device__ float3 rotatez(float3 p,float a){float s=cl_sin(a),c=cl_cos(a);return float3(c*p.x-s*p.y,s*p.x+c*p.y,p.z);}

__device__ float3 boundary_eval(float3 p,float r,float angle,int gate,float3* wallnormal,float3* wallvelocity,const float4* bounds,int* work){
 float3 start=p;*wallnormal=float3(0);*wallvelocity=float3(0);

 return plant_boundary(p,r,angle,bounds,wallnormal,wallvelocity);





















































}
__device__ float3 boundaries(float3 p,float r,float angle,int gate,float3* wn,float3* wv,const float4* bounds){int work[2]={0,0};return boundary_eval(p,r,angle,gate,wn,wv,bounds,work);}



















extern "C" __global__ void inspect_boundaries(const float4* points,int n,float r,float angle,int gate,const float4* bounds,
 float4* projected,float4* normals,float4* velocities){
 int i=get_global_id(0);if(i>=n)return;



 float3 wn,wv;int work[2]={0,0};float3 p=boundary_eval(points[i].xyz(),r,angle,gate,&wn,&wv,bounds,work);
 projected[i]=float4(p,points[i].w);normals[i]=float4(wn,(float)work[0]);velocities[i]=float4(wv,(float)work[1]);
}









extern "C" __global__ void solve(const float4* pos,const float4* old,float4* next,const int* head,const int* link,int n,float r,float cell,int nx,int ny,int nz,float angle,int gate,float mu



 ,const float4* bounds,int* error






 ){
 int i=get_global_id(0);if(i>=n)return;float3 ac=float3(0);float3 p=pos[i].xyz();int3 q=convert_int3(cl_floor((p+float3(.46f,.26f,.61f))/cell));float3 correction=float3(0);








 {
 for(int z=-1;z<=1;z++)for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){
  int3 c=q+int3(x,y,z);

  int j=head[plant_hash(c)];while(j>=0){if(j!=i&&all(convert_int3(cl_floor((pos[j].xyz()+float3(.46f,.26f,.61f))/cell))==c)){




correction+=pair_correction(pos[i],pos[j],old[i].xyz(),old[j].xyz(),i,j,r,mu



 );}j=link[j];}
 }
 }
 r=grain_radius(pos[i].w,r);float l=length(correction);





 if(l>r*.35f)correction*=r*.35f/l;




 float3 wn,wv;float3 unbounded=p+correction;

 p=plant_boundary_ref(unbounded,r,angle,bounds,&wn,&wv,old[i].xyz());







